2px}.api-entry-main small{display:block;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#99a3aa;margin-top:5px}.api-method{background:#e8f3ff;color:#2970bb;min-width:42px;text-align:center;padding:5px 7px;border-radius:6px;font-size:11px;font-weight:900;letter-spacing:.4px}.api-method.post{background:#fff2e9;color:#c66a32}.api-method.put{background:#ede8ff;color:#6a56b6}.api-method.delete{background:#ffeded;color:#c34c4c}.api-detail-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.api-detail h3{font-size:18px;margin:0;flex:1}.role-chip{font-size:11px;background:#f0f4f4;border-radius:15px;color:#64748b;padding:6px 9px}.endpoint{display:block;padding:12px;background:#f5f7f7;border:1px solid #edf0f0;border-radius:8px;word-break:break-all;margin:16px 0 8px;font-size:12px}.source{font-size:11px;color:#97a1a8}.api-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:20px}.api-form label{font-size:12px;font-weight:700;display:block;min-width:0}.field-type{font-weight:400;color:#99a2a5;margin-left:5px;font-size:11px}.api-form input,.api-form select,.api-form textarea,.token-entry input,.api-search{outline:0;border:1px solid #e2e8e8;border-radius:9px;padding:11px 12px;background:white;color:#233541;font-size:12px;margin-top:7px;box-sizing:border-box;width:100%;font-family:inherit}.api-form input:focus,.api-form textarea:focus,.token-entry input:focus,.api-search:focus{border-color:#0ea5e9;box-shadow:0 0 0 3px #e0f2fe}.api-form textarea{resize:vertical;font-family:monospace}.field-full{grid-column:1/-1}.danger-confirm{background:#fff7ed;border-radius:8px;padding:12px;color:#a65e30;display:flex!important;align-items:center;gap:8px}.danger-confirm input{width:15px;margin:0;accent-color:#ba6b25}.footer-actions{display:flex;gap:14px;align-items:center}.submit-action{background:#0ea5e9;color:#fff;border:none;border-radius:10px;padding:12px 24px;cursor:pointer;font-weight:700}.submit-action:disabled{opacity:.5}.hint{font-size:11px;color:#94a3b8}.response{margin-top:20px;border-radius:12px;background:#f8fafc;padding:16px;border:1px solid #e2e8f0}.response.error{background:#fff8f4;border-color:#f6e8d9}.response strong{font-size:12px}.response pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:390px;overflow:auto;font-size:12px;line-height:1.65}.response p{color:#94a3b8;font-size:12px}.empty-result{text-align:center;color:#a6aeaf;font-size:12px;padding:20px}
